const helpTopics = [
['Getting started','Start a video project','Enter a video title, audience and purpose. Choose Landscape for a standard video, Shorts for a vertical video, or Square. Choose language and visual style. Add scenes in story order, fill in their instructions, then export an AI production brief.'],
['Getting started','What this program creates','Framecraft creates an organized production plan. It stores your uploaded media in this browser and exports instructions for your chosen AI tool. It does not generate or transform footage, render a finished movie, download website videos, or upload to YouTube. Capabilities such as video-to-video conversion depend on the external tool you use.'],
['Scenes','Opening, homepage or title card','Select Opening / title card. Enter the opening headline in On-screen text, set a background color, and upload reference images or describe an image to generate. Use How should the images change? for cropping, background removal, colors or other edits. Image movement and Transition describe the intended animation.'],
['Scenes','Text, explanations and storytelling','Use Text / explanation for educational material, descriptions, tutorials or story narration. Put visible captions in On-screen text, the scene’s meaning in Content & direction, and spoken words in Narration script. Duration describes the planned timing.'],
['Scenes','Repeat, duplicate and reorder scenes','Click Add scene for each new part. Select a scene tab to edit it. Duplicate copies the settings and references; arrows move the scene earlier or later. The × button deletes a scene from the plan. At least one scene must remain. Export JSON before making changes you may want to undo.'],
['Media','Upload images, video and audio','In the scene editor, use Choose images, Upload source footage, or Music, voice or sound effects. Multiple files can be selected. Enter instructions explaining each filename’s role and order. Files stay on this browser/device; keep originals for your AI tool. Large files can exceed browser storage.'],
['Media','Use a clip downloaded from a website','Download the clip separately, then select it under Video clips → Upload source footage. Describe the cuts or transformation in Clip descriptions & editing instructions. This app does not fetch clips from links. Use footage you have permission to modify.'],
['AI revisions','Turn real objects into a cartoon movie','Upload source footage. Choose Animated as the visual style and write: “Turn the real objects into colorful cartoon characters. Preserve their motion and camera angles. Keep the character design consistent throughout.” Export the brief and supply it with the footage to an AI tool supporting video-to-video transformation. Results depend on that tool.'],
['AI revisions','Reload AI-modified clips for another edit','Open the scene and scroll to Video clips → AI clip revisions → Reload AI-generated or modified clips. Choose video clips to upload an AI result. Each upload receives a revision number and a playback control. Write the next changes in Next revision instructions. Export again: the latest revision is named as the input while earlier versions remain listed.'],
['AI revisions','Choose conversion and output settings','Under AI clip revisions, choose MP4, WebM or MOV, a resolution, and frame rate. These are requested output settings in the brief; they do not convert the uploaded file in this app. Playback depends on your browser and the video codec. If a clip will not play, convert it with an external editor to a browser-supported format, such as MP4 with H.264 video.'],
['Voice & music','Narration, language and voice direction','Choose the project Language, enter Narration script for each scene, and select Voice style. Voice direction can specify pacing, emotion, pronunciation and pauses. Select No voiceover if no spoken track is wanted. Give your AI tool explicit translation instructions when your script is in a different language.'],
['Voice & music','Music and sound effects','Choose a Background music mood or Custom / uploaded. Enter instruments, tempo and mood in Music description. Add sound effects by name, timing and filename. Upload audio references as needed. Music volume is a requested mix level; the brief also requests ducking under narration. Audio is mixed by your external tool.'],
['Export & import','Markdown or JSON: which should I choose?','Choose AI production brief (.md) for readable instructions to an AI assistant or editor. Choose Structured project (.json) to preserve editable scenes, settings, file references and revision information. Download both if you want a production handoff and a project backup. Neither format embeds the media files.'],
['Export & import','Import and resume a saved project','Click Import project JSON at the bottom of the planner and choose a JSON file exported by Framecraft. Markdown briefs cannot be imported as projects. Import replaces the current plan; export its JSON first if you want to keep it. Media stored in this browser may still be available; on a different device, re-upload your originals and returned clips.'],
['Export & import','Subtitles, thumbnails and YouTube upload materials','Use Finishing touches checkboxes to request subtitles, thumbnail concepts, a title, description, tags or chapters. Export the brief and source media to your AI tool. Review its final video and materials, then upload them to YouTube yourself. Checkboxes request deliverables; they do not generate them inside Framecraft.'],
['Creative examples','Travel, products, lessons and stories','Travel vlog: opening headline, scenery clips, narrated highlights, closing. Product demo: reference images, demonstration clips, benefit captions and a call to action. Lesson: repeat explanation scenes with diagrams and narration. Cartoon story: describe consistent characters, transform source clips externally, then reload revisions. Music montage: order clips and describe pacing, transitions and soundtrack.'],
['Troubleshooting','Saving, missing files and preview limits','Settings save automatically in this browser; uploaded media uses browser storage. Clearing browser data or switching devices can remove access to saved work. Back up JSON and keep media separately. Scene preview is a text/image layout guide, not a rendered timeline. Imported references without media must be uploaded again. If new features are missing, refresh the page.']
];
const helpButton=document.createElement('button');helpButton.className='secondary';helpButton.id='help-button';helpButton.textContent='? Help & examples';
const headerActions=document.createElement('div');headerActions.className='header-actions';$('export').before(headerActions);headerActions.append(helpButton,$('export'));
const helpDialog=document.createElement('dialog');helpDialog.className='help-dialog';helpDialog.setAttribute('aria-labelledby','help-title');helpDialog.innerHTML=`<div class="section-head"><div><h2 id="help-title">Help & creative guide</h2><p>Find a feature, learn the workflow, or explore an idea.</p></div><button class="secondary" id="help-close" aria-label="Close help">×</button></div><div class="grid two"><label>Search help<input id="help-search" type="search" placeholder="Try cartoon, reload, music or import"></label><label>Topic<select id="help-category"><option>All topics</option>${[...new Set(helpTopics.map(t=>t[0]))].map(t=>`<option>${esc(t)}</option>`).join('')}</select></label></div><div id="help-results"></div><p class="footnote">Your video stays in the planner while you browse this guide.</p>`;document.body.append(helpDialog);
function renderHelp(){const q=$('help-search').value.trim().toLowerCase(),category=$('help-category').value;const results=helpTopics.filter(t=>(category==='All topics'||t[0]===category)&&t.join(' ').toLowerCase().includes(q));$('help-results').innerHTML=results.length?results.map(t=>`<details class="help-topic" ${q?'open':''}><summary>${esc(t[1])}<span>${esc(t[0])}</span></summary><p>${esc(t[2])}</p></details>`).join(''):'<p role="status">No matching topics. Try another word or choose All topics.</p>';}
helpButton.onclick=()=>{renderHelp();helpDialog.showModal();$('help-search').focus()};$('help-close').onclick=()=>helpDialog.close();helpDialog.addEventListener('close',()=>helpButton.focus());$('help-search').oninput=renderHelp;$('help-category').onchange=renderHelp;
